/**
 * The learned local capability snapshot.
 *
 * The plugin used to bundle a static pi-ai / models.dev snapshot; most relay
 * providers publish neither reasoning ladders nor context windows, so that
 * snapshot aged quickly and had to be regenerated by hand. It is gone: the
 * replacement is this store, seeded by the settings page's "verify all
 * models" run (public catalogs plus the checker model the user picked) and
 * persisted in `$DSH_HOME/dsh-model-visibility/learned.json`.
 *
 * Facts are keyed by the exact advertised model ID, including its namespace.
 * Public facts cannot propagate through the legacy loose alias index; optional
 * public alias matches are recorded separately as advisory for their target ID.
 * Fields mirror the provider schema where possible so writes into provider
 * settings and learned facts stay one transform apart.
 *
 * The Host reads the file synchronously and re-reads it when the mtime
 * changes, following the same pattern as `lib/model-overrides.js`: a hand
 * edit of `learned.json` is enough to apply a fix.
 *
 * @module lib/learned-catalog
 */
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

import { MODEL_KINDS } from './capability-catalog.js'
import { addModelAlias, exactModelIdentity, modelAliasCandidates } from './model-id.js'
import { sanitizeEfforts, sanitizeModalities, text } from './model-overrides.js'

// Older aliases may have matched different variants (such as :batch).
const PUBLIC_ALIAS_VERSION = 1
export const PUBLIC_CATALOG_REVISION = 1

/** Absolute path of the learned snapshot below `$DSH_HOME`. */
export function learnedFile(home) {
  const base = home || process.env.DSH_HOME || path.join(os.homedir(), '.dsh')
  return path.join(base, 'dsh-model-visibility', 'learned.json')
}

/**
 * Normalize one verified fact into the store's detached record.
 * @param input - a check result entry, possibly malformed.
 * @returns `{ id, idSource, entry }` or undefined when nothing usable remains.
 */
function reconcileReasoning(entry) {
  if (entry.reasoning === false) delete entry.reasoningEfforts
  if (!entry.reasoningEfforts?.some(effort => effort.id === entry.defaultEffort)) delete entry.defaultEffort
}

const EVIDENCE_FIELDS = new Set(['kind', 'input', 'output', 'contextWindow', 'maxTokens', 'reasoning', 'reasoningEfforts', 'defaultEffort'])
const fieldKey = field => field === 'kind' ? 'type' : field

function evidenceFor(entry, ...groups) {
  const urls = new Map()
  for (const group of groups) {
    for (const item of group ?? []) {
      try {
        const url = new URL(item?.url)
        if (url.protocol !== 'https:' || url.username || url.password || !Array.isArray(item.fields)) continue
        const fields = item.fields.filter(field => EVIDENCE_FIELDS.has(field) && entry[fieldKey(field)] !== undefined)
        if (fields.length === 0) continue
        const existing = urls.get(url.href)
        if (existing) fields.forEach(field => existing.add(field))
        else if (urls.size < 8 * EVIDENCE_FIELDS.size) urls.set(url.href, new Set(fields))
      } catch { /* Invalid external citation. */ }
    }
  }
  return [...urls].map(([url, fields]) => ({ url, fields: [...fields] }))
}

export function sanitizeLearned(input) {
  if (input === null || typeof input !== 'object') return undefined
  const id =
    text(input.id) ??
    (input.provider !== undefined && input.model !== undefined
      ? text(input.model)
      : undefined)
  if (id === undefined || text(id) === '') return undefined
  const entry = {}
  if (typeof input.type === 'string' && MODEL_KINDS.includes(input.type)) entry.type = input.type
  const inputModalities = sanitizeModalities(input.input)
  if (inputModalities !== undefined) entry.input = inputModalities
  const output = sanitizeModalities(input.output)
  if (output !== undefined) entry.output = output
  if (Number.isSafeInteger(input.contextWindow) && input.contextWindow > 0) {
    entry.contextWindow = input.contextWindow
  }
  if (Number.isSafeInteger(input.maxTokens) && input.maxTokens > 0) entry.maxTokens = input.maxTokens
  const efforts = sanitizeEfforts(input.reasoningEfforts ?? input.efforts)
  if (efforts !== undefined) entry.reasoningEfforts = efforts
  const defaultEffort = text(input.defaultEffort)
  if (defaultEffort !== undefined) entry.defaultEffort = defaultEffort
  if (typeof input.reasoning === 'boolean') entry.reasoning = input.reasoning
  else if (efforts !== undefined) entry.reasoning = true
  reconcileReasoning(entry)
  const provider = text(input.provider)
  if (provider !== undefined) entry.provider = provider
  if (entry.reasoningEfforts && ['models.dev', 'OpenRouter'].includes(input.reasoningCatalog)) entry.reasoningCatalog = input.reasoningCatalog
  const lookupId = exactModelIdentity(input.publicLookupId)
  if (lookupId) entry.publicLookupId = lookupId
  if (input.publicCatalogRevision === PUBLIC_CATALOG_REVISION) entry.publicCatalogRevision = PUBLIC_CATALOG_REVISION
  const reference = input.publicReasoning
  if (reference && typeof reference === 'object' && sanitizeEfforts(reference.reasoningEfforts)) {
    const levels = sanitizeEfforts(reference.reasoningEfforts)
    entry.publicReasoning = {
      reasoningEfforts: levels,
      ...(levels.some(level => level.id === reference.defaultEffort) ? { defaultEffort: reference.defaultEffort } : {}),
      ...(['models.dev', 'OpenRouter'].includes(reference.reasoningCatalog) ? { reasoningCatalog: reference.reasoningCatalog } : {}),
      ...(exactModelIdentity(reference.publicLookupId) ? { publicLookupId: exactModelIdentity(reference.publicLookupId) } : {}),
    }
  }
  const declared =
    entry.type !== undefined ||
    entry.input !== undefined ||
    entry.output !== undefined ||
    entry.contextWindow !== undefined ||
    entry.maxTokens !== undefined ||
    entry.reasoningEfforts !== undefined ||
    entry.reasoning !== undefined
  if (!declared) return undefined
  if (Array.isArray(input.evidence)) {
    const evidence = evidenceFor(entry, input.evidence)
    if (evidence.length) entry.evidence = evidence
  }
  const origins = Array.isArray(input.origins)
    ? [...new Set(input.origins.filter((item) => item === 'public' || item === 'checker' || item === 'manual'))]
    : []
  const verifiedAt = Number(input.verifiedAt)
  return {
    id,
    idSource: typeof input.idSource === 'string' ? input.idSource : 'id',
    entry: {
      ...entry,
      ...(input.publicAlias === true ? {
        publicAlias: true,
        ...(input.publicAliasVersion === PUBLIC_ALIAS_VERSION ? { publicAliasVersion: PUBLIC_ALIAS_VERSION } : {}),
      } : {}),
      ...(input.legacyPublic === true ? { legacyPublic: true } : {}),
      verifiedAt: Number.isSafeInteger(verifiedAt) && verifiedAt > 0 ? verifiedAt : Date.now(),
      ...(origins.length > 0 ? { origins } : { origins: [] }),
      ...(input.checker !== null && typeof input.checker === 'object'
        ? { checker: input.checker }
        : {}),
    },
  }
}

/**
 * A file-backed store of verified capability facts, keyed by exact API ID.
 *
 * @param options - `{ file?, home?, logger?, now? }`.
 * @returns `{ file, meta, list, get, upsertEntries, invalidate }`.
 */
export function createLearnedCatalog(options = {}) {
  const file = options.file || learnedFile(options.home)
  const logger = options.logger ?? console
  const now = typeof options.now === 'function' ? options.now : Date.now
  /** Case-insensitive full IDs and conservative aliases, rebuilt on change. */
  let folded = new Map()
  let aliases = new Map()
  /** canonical id -> detached record (entry keys, provider shape). */
  let records = new Map()
  let store = null
  let loaded = false
  let loadedMtime = -Infinity

  const warn = (message, error) => {
    if (typeof logger.warn === 'function') {
      logger.warn(message)
      if (error !== undefined) logger.warn(error)
    }
  }

  const mtimeOf = () => {
    try {
      return fs.statSync(file).mtimeMs
    } catch (_error) {
      return -Infinity
    }
  }

  const buildIndex = () => {
    folded = new Map()
    aliases = new Map()
    for (const id of records.keys()) {
      const key = id.toLowerCase()
      folded.set(key, folded.has(key) ? null : id)
      // Public records still disambiguate spelling, but can't supply a fuzzy fact.
      addModelAlias(aliases, id)
    }
  }

  const readRecord = (raw) => {
    const sanitized = sanitizeLearned(raw)
    if (sanitized === undefined) return undefined
    const record = sanitized.entry
    return { id: sanitized.id, ...record }
  }

  const load = (force = false) => {
    const mtime = mtimeOf()
    if (!force && loaded && mtime === loadedMtime) return
    loaded = true
    loadedMtime = mtime
    records = new Map()
    store = null
    if (mtime === -Infinity) {
      buildIndex()
      return
    }
    try {
      const parsed = JSON.parse(fs.readFileSync(file, 'utf8'))
      store = parsed !== null && typeof parsed === 'object' ? parsed : null
      const source =
        store !== null && store.models !== null && typeof store.models === 'object'
          ? store.models
          : null
      if (source !== null) {
        for (const raw of Object.values(source)) {
          const record = readRecord(raw)
          if (record === undefined) continue
          const key = exactModelIdentity(record.id)
          if ((store.version !== 2 && record.origins?.includes('public')) ||
              (record.publicAlias && record.publicAliasVersion !== PUBLIC_ALIAS_VERSION)) record.legacyPublic = true
          if (key !== undefined && !records.has(key)) records.set(key, record)
        }
      }
    } catch (error) {
      warn('model-visibility: could not read the learned snapshot; starting empty', error)
      store = null
    }
    buildIndex()
  }

  const persistLocked = (nextRecords, checker = store?.checker) => {
    const body = {
      version: 2,
      ...(checker !== undefined ? { checker } : {}),
      updatedAt: now(),
      models: Object.fromEntries(nextRecords),
    }
    const temp = `${file}.${process.pid}.tmp`
    try {
      fs.mkdirSync(path.dirname(file), { recursive: true })
      fs.writeFileSync(temp, `${JSON.stringify(body, null, 2)}\n`)
      fs.renameSync(temp, file)
    } catch (error) {
      try { fs.unlinkSync(temp) } catch { /* No temporary file, or already inaccessible. */ }
      throw new Error('Could not save the learned snapshot: ' + error.message, { cause: error })
    }
    records = nextRecords
    store = body
    loadedMtime = mtimeOf()
    buildIndex()
  }

  /** Footer facts for the settings page (full file read). */
  const meta = () => {
    load()
    return {
      file,
      models: records.size,
      updatedAt:
        store !== null && Number.isSafeInteger(store.updatedAt) ? store.updatedAt : undefined,
      checker: store !== null && store.checker !== null && typeof store.checker === 'object' ? store.checker : undefined,
    }
  }

  /** Detached copies of every stored fact, in exact-key order. */
  const list = () => {
    load()
    return [...records.values()].map((record) => ({ ...record }))
  }

  /** Canonical identity only: never skip a new verification target on a fuzzy match. */
  const getExact = (value) => {
    const key = exactModelIdentity(value)
    if (key === undefined) return undefined
    load()
    const record = records.get(key)
    return record === undefined ? undefined : { ...record }
  }

  /** Exact first; fall back only to a unique conservative non-public alias. */
  const get = (value) => {
    const id = exactModelIdentity(value)
    if (id === undefined) return undefined
    load()
    const exact = records.get(id)
    if (exact !== undefined) return exact.legacyPublic ? undefined : { ...exact }
    const foldedId = folded.get(id.toLowerCase())
    const candidates = foldedId === undefined ? modelAliasCandidates(aliases, id) : [foldedId]
    if (candidates.length !== 1) return undefined
    const record = records.get(candidates[0])
    if (record === undefined || record.legacyPublic || record.publicAlias || record.origins?.includes('public')) return undefined
    return { ...record }
  }

  /**
   * Merge verified facts in; a newer verification wins field by field.
   *
   * The same model may arrive twice (its id from one relay, a corrected id
   * from the checker), so records merge instead of replacing. An older batch
   * may fill fields the newer batch did not know, but must never replace a
   * newer declaration or make it look freshly verified.
   * @param inputs - check results, each `{ id | provider+model, …facts }`.
   * @param extra - provenance for the whole call: `verifiedAt`, `origins`,
   *   `checker`. `origins` is merged into each record so a later public-only
   *   pass appends `public` next to an earlier `checker` instead of replacing
   *   it (which is what made "publicOnly: 0" look like a missing source).
   */
  const upsertEntries = (inputs, extra = {}) => {
    // A verify sweep now flushes one array of facts per batch instead of one
    // call per model. Reloading by force for every call forced a full file read
    // and a full rewrite per model (199 reads + 199 writes for 200 models).
    load(true)
    const source = Array.isArray(inputs) ? inputs : [inputs]
    const nextRecords = new Map(records)
    let changed = false
    for (const raw of source) {
      const sanitized = sanitizeLearned(raw)
      if (sanitized === undefined) continue
      // Call-side provenance beats the entry's own stamps: the orchestrator
      // knows the run that produced the fact. An entry that carries its own
      // `origins` keeps them, so a public-only row stays `['public']`.
      const provenance = {}
      if (extra?.verifiedAt !== undefined) provenance.verifiedAt = extra.verifiedAt
      if (extra?.origins !== undefined && raw?.origins === undefined) provenance.origins = extra.origins
      if (extra?.checker !== undefined) provenance.checker = extra.checker
      const record = { provider: raw?.provider, ...sanitized.entry, ...provenance, id: sanitized.id }
      if (record.publicAlias && !record.legacyPublic) record.publicAliasVersion = PUBLIC_ALIAS_VERSION
      const key = exactModelIdentity(record.id)
      const existing = nextRecords.get(key)
      if (record.publicAlias && existing && !existing.legacyPublic && !existing.publicAlias) {
        if (record.publicCatalogRevision !== PUBLIC_CATALOG_REVISION) continue
        const next = { ...existing, publicCatalogRevision: record.publicCatalogRevision }
        // Keep relaxed reasoning advisory. Never change exact context, inputs
        // or any other facts used to make requests.
        if (record.reasoningEfforts?.length) next.publicReasoning = {
          reasoningEfforts: record.reasoningEfforts,
          ...(record.defaultEffort ? { defaultEffort: record.defaultEffort } : {}),
          ...(record.reasoningCatalog ? { reasoningCatalog: record.reasoningCatalog } : {}),
          ...(record.publicLookupId ? { publicLookupId: record.publicLookupId } : {}),
        }
        if (JSON.stringify(next) !== JSON.stringify(existing)) { nextRecords.set(key, next); changed = true }
        continue
      }
      if (existing === undefined || existing.legacyPublic || (existing.publicAlias && !record.publicAlias)) {
        nextRecords.set(key, record)
        changed = true
        continue
      }
      const next = { ...existing }
      const incomingIsNewer = (record.verifiedAt ?? 0) >= (existing.verifiedAt ?? 0)
      // A default belongs to its ladder, and a newer explicit "no reasoning"
      // must remove rather than leave stale controls in the persisted record.
      const protect = record.publicCatalogRevision === PUBLIC_CATALOG_REVISION && record.origins.length === 1 && record.origins[0] === 'public' &&
        (existing.origins?.includes('checker') || existing.origins?.includes('manual'))
      if (incomingIsNewer && record.reasoningEfforts !== undefined && !(protect && existing.reasoningEfforts !== undefined)) {
        delete next.defaultEffort
        delete next.reasoningCatalog
      }
      const incomingFields = new Set()
      for (const [field, value] of Object.entries(record)) {
        if (value === undefined || value === null || field === 'evidence') continue
        if ((!incomingIsNewer || protect) && existing[field] !== undefined && !['origins', 'publicCatalogRevision'].includes(field)) continue
        if (protect && existing.reasoning !== undefined && ['reasoningEfforts', 'defaultEffort', 'reasoningCatalog'].includes(field) &&
          (existing.reasoning === false || existing.reasoningEfforts !== undefined)) continue
        if (field === 'verifiedAt') {
          next.verifiedAt = Math.max(existing.verifiedAt ?? 0, value)
          continue
        }
        if (field === 'origins' && Array.isArray(existing.origins)) {
          const union = [...new Set([...existing.origins, ...value])]
          if (JSON.stringify(union) === JSON.stringify(existing.origins)) continue
          next.origins = union
          continue
        }
        next[field] = value
        incomingFields.add(field)
      }
      reconcileReasoning(next)
      if (!next.reasoningEfforts) delete next.reasoningCatalog
      if (!next.publicAlias && record.publicCatalogRevision === PUBLIC_CATALOG_REVISION) delete next.publicReasoning
      // Provenance belongs to the field value that won, not to the record as a
      // whole.  A replacement without a citation must also clear its old link.
      const select = (entries, fromIncoming) => entries?.map(item => ({
        ...item, fields: item.fields.filter(field => incomingFields.has(fieldKey(field)) === fromIncoming),
      }))
      const evidence = evidenceFor(next, select(existing.evidence, false), select(record.evidence, true))
      if (evidence.length > 0) next.evidence = evidence
      else delete next.evidence
      if (JSON.stringify(next) !== JSON.stringify(existing)) {
        nextRecords.set(key, next)
        changed = true
      }
    }
    if (changed) persistLocked(nextRecords, extra?.checker)
  }

  /** Forget the memoized copy; the next read consults the file again. */
  const invalidate = () => {
    loaded = false
    loadedMtime = -Infinity
  }

  /** An exact-only run no longer surfaces the preceding run's alias assumptions. */
  const dropPublicAliases = () => {
    load(true)
    const nextRecords = new Map()
    let changed = false
    for (const [id, record] of records) {
      if (record.publicAlias) { changed = true; continue }
      if (record.publicReasoning) {
        const next = { ...record }
        delete next.publicReasoning
        delete next.publicCatalogRevision
        nextRecords.set(id, next)
        changed = true
      } else nextRecords.set(id, record)
    }
    if (!changed) return
    persistLocked(nextRecords)
  }

  return { file, meta, list, get, getExact, upsertEntries, invalidate, dropPublicAliases }
}
